// This constrained decoding strategy is designed to solve math word problems involving arithmetic operations on symbolic quantities. The strategy uses a combination of constrained steps and soft constrained steps to ensure that the generated text remains within the grammar of the problem while also encouraging the selection of correct arithmetic operations.
// CSD_RATIONALE_END

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  decreases maxSteps - steps
{
  if helpers.DeadEndDetection(parser, currentConstrained, 2) {
    currentConstrained := helpers.RollbackToValidPrefix(parser, currentConstrained);
  }

  var next, isValid := helpers.SoftConstrainedStep(lm, parser, prompt, currentConstrained, 0.1);
  if !isValid {
    next := helpers.ConstrainedStep(lm, parser, prompt, currentConstrained);
  }

  generated := generated + [next];
  currentConstrained := currentConstrained + [next];

  steps := steps + 1;
}

